<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import { api } from "@/api";
import { useAppStore } from "@/stores/app";
import type { MetricDefinition, SellerOption } from "@/types";

const store = useAppStore();
const activeTab = ref("metrics");
const metrics = ref<MetricDefinition[]>([]);
const metricKeyword = ref("");
const metricPage = ref(1);
const metricPageSize = 8;
const sellers = ref<SellerOption[]>([]);
const targetRows = ref<Array<Record<string, any>>>([]);
const targetTotal = ref(0);
const targetPage = ref(1);
const targetPageSize = 8;
const targetLoading = ref(false);
const filters = ref({ metric: "", seller_id: "", version: "", period_start: "", period_end: "" });
const form = ref({ metric: "gmv", seller_id: "", period_start: "", period_end: "", target_value: 0, version: "v1", effective_at: "" });
const isPlatform = computed(() => store.account?.role === "admin" && (store.account?.sellerGrants?.length ?? 0) === 0);
const visibleMetrics = computed(() => { const key = metricKeyword.value.trim().toLowerCase(); return metrics.value.filter((item) => !key || `${item.metric_name} ${item.display_name ?? ""} ${item.description ?? ""}`.toLowerCase().includes(key)); });
const pagedMetrics = computed(() => visibleMetrics.value.slice((metricPage.value - 1) * metricPageSize, metricPage.value * metricPageSize));
function attributionScope(metric: MetricDefinition) { return metric.attribution?.support_by_scope[isPlatform.value ? "platform" : "seller"]; }
function attributionStatusLabel(metric: MetricDefinition) { const status = attributionScope(metric)?.status; return status === "supported" ? "已支持" : status === "scope_unavailable" ? "此范围不可用" : "未支持"; }
function attributionStatusType(metric: MetricDefinition) { const status = attributionScope(metric)?.status; return status === "supported" ? "success" : status === "scope_unavailable" ? "info" : "warning"; }
function attributionDetails(metric: MetricDefinition) { const scope = attributionScope(metric); if (!scope) return "没有归因能力声明"; const required = Object.entries(scope.required_data).map(([method, fields]) => `${method}: ${fields.join("、")}`).join("；"); return [scope.limitation, scope.methods.length ? `方法：${scope.methods.join("、")}` : "尚未注册可执行方法", scope.dimensions.length ? `拆解维度：${scope.dimensions.join("、")}` : "没有已声明维度", required ? `所需数据：${required}` : "未登记分子/分母或分组统计契约"].filter(Boolean).join("\n"); }
function targetQuery() { const params = new URLSearchParams({ offset: String((targetPage.value - 1) * targetPageSize), limit: String(targetPageSize) }); if (filters.value.metric) params.set("metric_name", filters.value.metric); if (filters.value.seller_id) params.set("seller_id", filters.value.seller_id); if (filters.value.version) params.set("version", filters.value.version); if (filters.value.period_start) params.set("period_start", filters.value.period_start); if (filters.value.period_end) params.set("period_end", filters.value.period_end); return params.toString(); }
async function loadTargets() { targetLoading.value = true; try { const result = await api.targets(store.auth, targetQuery()); targetRows.value = result.items; targetTotal.value = result.total; } catch (error) { ElMessage.error(error instanceof Error ? error.message : "读取目标失败"); } finally { targetLoading.value = false; } }
async function load() { try { metrics.value = await api.metrics(store.auth, isPlatform.value ? "platform" : "seller"); sellers.value = isPlatform.value ? (await api.sellers(store.auth, "")).items : (store.account?.sellerGrants ?? []).map((item) => ({ seller_id: item.seller_id, label: item.seller_id })); if (metrics.value.length && !metrics.value.some((item) => item.metric_name === form.value.metric)) form.value.metric = metrics.value[0].metric_name; form.value.seller_id = sellers.value[0]?.seller_id ?? ""; const now = new Date(); form.value.period_start = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-01`; form.value.period_end = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().slice(0, 10); form.value.effective_at = form.value.period_start; await loadTargets(); } catch (error) { ElMessage.error(error instanceof Error ? error.message : "读取指标失败"); } }
async function save() { try { const { metric, ...payload } = form.value; await api.saveTarget(store.auth, metric, { ...payload, created_by: store.profile.id }); ElMessage.success("目标已保存"); activeTab.value = "targets"; targetPage.value = 1; await loadTargets(); } catch (error) { ElMessage.error(error instanceof Error ? error.message : "保存目标失败"); } }
async function remove(row: Record<string, any>) { try { await ElMessageBox.confirm("删除后，该版本目标将不再参与后续报告比较。", "确认删除目标", { type: "warning" }); const params = new URLSearchParams({ period_start: String(row.period_start), period_end: String(row.period_end), version: String(row.version) }); if (row.seller_id) params.set("seller_id", String(row.seller_id)); const result = await api.deleteTarget(store.auth, String(row.metric_name), params.toString()); if (result.deleted) { ElMessage.success("目标已删除"); await loadTargets(); } } catch (error) { if (error !== "cancel" && error !== "close") ElMessage.error(error instanceof Error ? error.message : "删除目标失败"); } }
onMounted(load);
</script>

<template>
  <div class="page metrics-page">
    <div class="page-title"><div><h1>指标与目标</h1><p>先查清指标口径，再按店铺和周期管理报告中的目标基准。</p></div></div>
    <el-tabs v-model="activeTab" class="metrics-tabs">
      <el-tab-pane label="指标定义" name="metrics"><el-card shadow="never"><template #header><div class="toolbar"><span>可用指标及归因能力 · {{ isPlatform ? "平台" : "店铺" }}范围</span><el-input v-model="metricKeyword" clearable placeholder="搜索指标名称、编码或说明" style="max-width: 320px" /></div></template><el-table :data="pagedMetrics" stripe><el-table-column prop="metric_name" label="指标编码" width="180" /><el-table-column prop="display_name" label="指标名称" width="180" /><el-table-column prop="unit" label="单位" width="90" /><el-table-column prop="description" label="口径说明" min-width="240" /><el-table-column label="归因能力" width="130"><template #default="{ row }"><el-tooltip placement="top" :content="attributionDetails(row)" effect="dark"><span class="capability-status"><el-tag size="small" :type="attributionStatusType(row)">{{ attributionStatusLabel(row) }}</el-tag><small v-if="attributionScope(row)?.methods?.length">{{ attributionScope(row)?.methods?.join(" / ") }}</small></span></el-tooltip></template></el-table-column></el-table><el-pagination v-if="visibleMetrics.length > metricPageSize" v-model:current-page="metricPage" :page-size="metricPageSize" layout="prev, pager, next, total" :total="visibleMetrics.length" background /></el-card></el-tab-pane>
      <el-tab-pane label="目标管理" name="targets"><el-card shadow="never" class="target-form-card"><template #header><div><strong>新增目标版本</strong><p class="muted">{{ isPlatform ? "平台管理员可为任意店铺设置目标。" : "你只能为自己被授权的店铺设置目标。" }}</p></div></template><el-form label-position="top" class="target-form"><el-form-item label="店铺"><el-select v-model="form.seller_id" filterable><el-option v-for="seller in sellers" :key="seller.seller_id" :label="seller.label || seller.seller_id" :value="seller.seller_id" /></el-select></el-form-item><el-form-item label="指标"><el-select v-model="form.metric" filterable><el-option v-for="metric in metrics" :key="metric.metric_name" :label="metric.display_name || metric.metric_name" :value="metric.metric_name" /></el-select></el-form-item><el-form-item label="目标周期"><div class="date-fields"><el-date-picker v-model="form.period_start" type="date" value-format="YYYY-MM-DD" /><span>至</span><el-date-picker v-model="form.period_end" type="date" value-format="YYYY-MM-DD" /></div></el-form-item><el-form-item label="目标值"><el-input-number v-model="form.target_value" :min="0" /></el-form-item><el-form-item label="版本"><el-input v-model="form.version" placeholder="例如 v1、2026Q3" /></el-form-item><el-form-item label="生效日期"><el-date-picker v-model="form.effective_at" type="date" value-format="YYYY-MM-DD" /></el-form-item><el-button type="primary" @click="save">保存目标</el-button></el-form></el-card><el-card shadow="never" class="target-list-card"><template #header><div class="toolbar"><span>目标记录</span><div class="target-filters"><el-select v-model="filters.seller_id" clearable filterable placeholder="全部店铺" @change="targetPage = 1; loadTargets()"><el-option v-for="seller in sellers" :key="seller.seller_id" :label="seller.label || seller.seller_id" :value="seller.seller_id" /></el-select><el-select v-model="filters.metric" clearable placeholder="全部指标" @change="targetPage = 1; loadTargets()"><el-option v-for="metric in metrics" :key="metric.metric_name" :label="metric.display_name || metric.metric_name" :value="metric.metric_name" /></el-select><el-input v-model="filters.version" clearable placeholder="版本" @keyup.enter="targetPage = 1; loadTargets()" /><el-button @click="targetPage = 1; loadTargets()">查询</el-button></div></div></template><el-table v-loading="targetLoading" :data="targetRows" stripe><el-table-column prop="seller_id" label="店铺" min-width="180" /><el-table-column prop="metric_name" label="指标" width="150" /><el-table-column label="目标周期" min-width="210"><template #default="{ row }">{{ row.period_start }} 至 {{ row.period_end }}</template></el-table-column><el-table-column prop="target_value" label="目标值" width="120" /><el-table-column prop="version" label="版本" width="100" /><el-table-column prop="effective_at" label="生效日期" width="130" /><el-table-column label="操作" width="90"><template #default="{ row }"><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-pagination v-if="targetTotal" v-model:current-page="targetPage" :page-size="targetPageSize" layout="prev, pager, next, total" :total="targetTotal" background @current-change="loadTargets" /><el-empty v-if="!targetLoading && !targetRows.length" description="暂无目标记录" /></el-card></el-tab-pane>
    </el-tabs>
    <div v-if="activeTab === 'targets'" class="target-date-filters"><el-date-picker v-model="filters.period_start" type="date" value-format="YYYY-MM-DD" placeholder="周期开始" /><el-date-picker v-model="filters.period_end" type="date" value-format="YYYY-MM-DD" placeholder="周期结束" /><el-button @click="targetPage = 1; loadTargets()">按周期查询</el-button></div>
  </div>
</template>

<style scoped>
.capability-status { display: inline-flex; flex-direction: column; align-items: flex-start; gap: 4px; }
.capability-status small { max-width: 120px; color: var(--el-text-color-secondary); overflow-wrap: anywhere; }
</style>
